"""Per-story git worktree lifecycle for parallel SE dispatch (issue #167).

The orchestrator creates a worktree before dispatching an SE agent, then
after the SE receipt verifies runs `commit` (an audited commit of the SE's
changes) and `merge` (branch back into main), removing the worktree after.
Timing is deterministic and orchestrator-managed — agents never create,
commit, or destroy worktrees themselves.

Flow per story: create → dispatch SE (works in the worktree, writes a
receipt) → SubagentStop verifies (replays in the worktree) → commit → merge.
The commit step exists because SEs produce code but do not commit, and
`merge` deliberately refuses a dirty worktree — so the orchestrator owns the
audited commit (carrying a `Synaptory-Story` trailer) between verify and
merge (#170 review).

Layout per story:
    worktree:  <project>/.synaptory/.worktrees/<story_id>
    branch:    synaptory/<story_id>
    ref:       wt://synaptory/<story_id>   (workspace_ref in dispatch payloads)

Safety invariants:
  * story ids are validated (no path traversal, no git-option injection).
  * destructive ops (worktree remove, branch delete) only ever target
    resolved paths under <project>/.synaptory/.worktrees/.
  * a dirty worktree is never auto-committed — merge refuses (exit 2).
  * a conflicted merge is aborted, leaving the main tree clean (exit 3).
  * all git calls: subprocess with shell=False and a 30s timeout.

CLI (JSON on stdout):
    python3 worktree_manager.py create --project-dir P --story-id US-042 [--base HEAD]
    python3 worktree_manager.py commit --project-dir P --story-id US-042 [--message M] [--author A]
    python3 worktree_manager.py merge  --project-dir P --story-id US-042 [--no-remove]
    python3 worktree_manager.py remove --project-dir P --story-id US-042 [--force]
    python3 worktree_manager.py list   --project-dir P [--stale]

Exit codes: 0 success · 1 error (git failure / bad input) · 2 dirty
worktree refused · 3 merge conflict (aborted).
"""

# NFR-PLUGIN-2: Python 3.9+. Annotations below use PEP 604 unions
# (`X | None`); the future-import defers evaluation so 3.9 doesn't
# choke at module-load time.
from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys
from typing import Any

GIT_TIMEOUT = 30  # seconds per git call
WORKTREES_RELDIR = os.path.join(".synaptory", ".worktrees")
BRANCH_PREFIX = "synaptory/"
EXCLUDE_LINE = ".synaptory/.worktrees/"

# Story ids become path components and branch names. Must start alnum (so no
# `-option` injection and no dot-prefixed relatives), then a conservative
# charset with `..` explicitly refused (path traversal + invalid refname).
_STORY_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,100}$")

# CLI exit codes
EXIT_OK = 0
EXIT_ERROR = 1
EXIT_DIRTY = 2
EXIT_CONFLICT = 3


# ─── Git plumbing ─────────────────────────────────────────────────────────────


def _git(cwd: str, *args: str) -> subprocess.CompletedProcess:
    """Run git in `cwd`. Never raises for git failures (check returncode);
    OS-level failures (git missing, timeout) surface as returncode 127
    with the message in stderr."""
    try:
        return subprocess.run(
            ["git", "-C", cwd, *args],
            shell=False,
            capture_output=True,
            text=True,
            timeout=GIT_TIMEOUT,
        )
    except (OSError, subprocess.TimeoutExpired, subprocess.SubprocessError) as e:
        return subprocess.CompletedProcess(
            args=["git", "-C", cwd, *args], returncode=127, stdout="", stderr=str(e)
        )


def _error(reason: str, **extra: Any) -> dict[str, Any]:
    out: dict[str, Any] = {"error": True, "reason": reason}
    out.update(extra)
    return out


def _validate_story_id(story_id: str) -> str | None:
    """Return an error string, or None if the story id is safe."""
    if not isinstance(story_id, str) or not _STORY_ID_RE.match(story_id):
        return f"invalid story id {story_id!r}: must match {_STORY_ID_RE.pattern}"
    if ".." in story_id:
        return f"invalid story id {story_id!r}: '..' not permitted"
    return None


def _worktree_path(project_dir: str, story_id: str) -> str | None:
    """Resolved worktree path for a story, or None if it escapes the
    managed .synaptory/.worktrees/ directory (defense in depth on top of
    story-id validation — this guard gates every destructive op)."""
    base = os.path.realpath(os.path.join(project_dir, WORKTREES_RELDIR))
    candidate = os.path.realpath(os.path.join(base, story_id))
    if os.path.commonpath([base, candidate]) != base or candidate == base:
        return None
    return candidate


def _branch_name(story_id: str) -> str:
    return BRANCH_PREFIX + story_id


def _branch_exists(project_dir: str, branch: str) -> bool:
    return (
        _git(project_dir, "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}").returncode
        == 0
    )


def _registered_worktrees(project_dir: str) -> list[dict[str, Any]] | None:
    """Parse `git worktree list --porcelain` into
    [{"path": ..., "branch": str | None}]. None on git failure."""
    proc = _git(project_dir, "worktree", "list", "--porcelain")
    if proc.returncode != 0:
        return None
    entries: list[dict[str, Any]] = []
    current: dict[str, Any] = {}
    for line in proc.stdout.splitlines():
        if not line.strip():
            if current:
                entries.append(current)
                current = {}
            continue
        if line.startswith("worktree "):
            current = {"path": line[len("worktree "):], "branch": None}
        elif line.startswith("branch ") and current:
            ref = line[len("branch "):]
            current["branch"] = ref[len("refs/heads/"):] if ref.startswith("refs/heads/") else ref
    if current:
        entries.append(current)
    return entries


def _find_registered(project_dir: str, wt_path: str) -> dict[str, Any] | None:
    for entry in _registered_worktrees(project_dir) or []:
        if os.path.realpath(entry["path"]) == wt_path:
            return entry
    return None


def _ensure_excluded(project_dir: str) -> None:
    """Append `.synaptory/.worktrees/` to <gitdir>/info/exclude so worktrees
    never show up in `git status` — without touching any tracked file
    (.gitignore stays clean). Best-effort."""
    proc = _git(project_dir, "rev-parse", "--git-common-dir")
    if proc.returncode != 0:
        return
    git_dir = proc.stdout.strip()
    if not os.path.isabs(git_dir):
        git_dir = os.path.join(project_dir, git_dir)
    exclude_path = os.path.join(git_dir, "info", "exclude")
    try:
        existing = ""
        if os.path.exists(exclude_path):
            with open(exclude_path, "r", encoding="utf-8") as f:
                existing = f.read()
        if EXCLUDE_LINE in existing.splitlines():
            return
        os.makedirs(os.path.dirname(exclude_path), exist_ok=True)
        with open(exclude_path, "a", encoding="utf-8") as f:
            if existing and not existing.endswith("\n"):
                f.write("\n")
            f.write(EXCLUDE_LINE + "\n")
    except OSError:
        pass


def _dirty_files(tree_dir: str) -> list[str] | None:
    """Paths with uncommitted changes (staged, unstaged, or untracked) in
    `tree_dir`. None on git failure."""
    proc = _git(tree_dir, "status", "--porcelain")
    if proc.returncode != 0:
        return None
    return [line[3:] for line in proc.stdout.splitlines() if line.strip()]


# ─── create ───────────────────────────────────────────────────────────────────


def create_worktree(project_dir: str, story_id: str, base: str = "HEAD") -> dict[str, Any]:
    """Create (or return the existing) per-story worktree.

    Idempotent: an already-registered worktree at the story path is
    returned with created=False; an existing branch is reused.
    """
    err = _validate_story_id(story_id)
    if err:
        return _error(err)
    wt_path = _worktree_path(project_dir, story_id)
    if wt_path is None:
        return _error(f"story id {story_id!r} resolves outside the managed worktrees dir")
    branch = _branch_name(story_id)

    _ensure_excluded(project_dir)

    payload = {
        "path": wt_path,
        "branch": branch,
        "workspace_ref": f"wt://{branch}",
        "created": False,
    }

    # Idempotent re-run: worktree already registered at this path.
    if _find_registered(project_dir, wt_path) is not None:
        return payload

    os.makedirs(os.path.dirname(wt_path), exist_ok=True)
    if _branch_exists(project_dir, branch):
        proc = _git(project_dir, "worktree", "add", wt_path, branch)
    else:
        proc = _git(project_dir, "worktree", "add", wt_path, "-b", branch, base)
    if proc.returncode != 0:
        return _error(f"git worktree add failed: {proc.stderr.strip()}")
    payload["created"] = True
    return payload


# ─── commit ─────────────────────────────────────────────────────────────────


def commit_worktree(
    project_dir: str,
    story_id: str,
    message: str | None = None,
    author: str | None = None,
) -> dict[str, Any]:
    """Orchestrator-owned audited commit of the SE's worktree changes (#170).

    An SE produces code in its worktree and writes a receipt, but does not
    commit; ``merge_worktree`` deliberately refuses a dirty worktree so it
    never merges over unreviewed uncommitted work. The orchestrator runs this
    step AFTER the SE receipt verifies (verification replays in the worktree,
    where the uncommitted changes still live) and BEFORE ``merge_worktree`` —
    it stages everything and records one audited commit carrying a
    ``Synaptory-Story`` trailer for provenance.

    Idempotent: a clean worktree commits nothing and returns committed=False
    with reason "clean" (not an error) so the standard verify → commit → merge
    flow is safe to re-run.
    """
    err = _validate_story_id(story_id)
    if err:
        return _error(err)
    wt_path = _worktree_path(project_dir, story_id)
    if wt_path is None:
        return _error(f"story id {story_id!r} resolves outside the managed worktrees dir")
    if not os.path.isdir(wt_path):
        return _error(f"worktree not found at {wt_path}")

    dirty = _dirty_files(wt_path)
    if dirty is None:
        return _error(f"could not read worktree status at {wt_path}")
    if not dirty:
        return {"committed": False, "reason": "clean", "branch": _branch_name(story_id)}

    add = _git(wt_path, "add", "-A")
    if add.returncode != 0:
        return _error(f"git add failed: {add.stderr.strip()}")

    msg = message or f"feat({story_id}): story worktree changes"
    msg = f"{msg}\n\nSynaptory-Story: {story_id}"
    commit_args = ["commit", "-m", msg]
    if author:
        commit_args += ["--author", author]
    proc = _git(wt_path, *commit_args)
    if proc.returncode != 0:
        return _error(f"git commit failed: {proc.stderr.strip() or proc.stdout.strip()}")

    head = _git(wt_path, "rev-parse", "HEAD").stdout.strip()
    return {
        "committed": True,
        "commit": head,
        "branch": _branch_name(story_id),
        "files": dirty,
    }


# ─── merge ────────────────────────────────────────────────────────────────────


def merge_worktree(project_dir: str, story_id: str, remove: bool = True) -> dict[str, Any]:
    """Merge the story branch into the main tree's HEAD (--no-ff).

    Refuses (never auto-commits) when the worktree has uncommitted changes.
    On conflict the merge is aborted and the main tree left clean; the
    worktree stays intact for manual resolution. On success the worktree
    and branch are removed unless remove=False.
    """
    err = _validate_story_id(story_id)
    if err:
        return _error(err)
    wt_path = _worktree_path(project_dir, story_id)
    if wt_path is None:
        return _error(f"story id {story_id!r} resolves outside the managed worktrees dir")
    branch = _branch_name(story_id)

    if not _branch_exists(project_dir, branch):
        return _error(f"branch {branch!r} does not exist")

    # Precondition: never merge over uncommitted worktree changes.
    if os.path.isdir(wt_path):
        dirty = _dirty_files(wt_path)
        if dirty is None:
            return _error(f"could not read worktree status at {wt_path}")
        if dirty:
            return {"merged": False, "reason": "worktree_dirty", "files": dirty}

    proc = _git(
        project_dir,
        "merge",
        "--no-ff",
        branch,
        "-m",
        f"merge({story_id}): story worktree",
    )
    if proc.returncode != 0:
        # A merge-in-progress (MERGE_HEAD present) means conflicts; anything
        # else (e.g. dirty main tree blocking the merge) never started.
        in_progress = (
            _git(project_dir, "rev-parse", "--quiet", "--verify", "MERGE_HEAD").returncode == 0
        )
        if in_progress:
            conflicted = _git(
                project_dir, "diff", "--name-only", "--diff-filter=U"
            ).stdout.splitlines()
            _git(project_dir, "merge", "--abort")
            return {"merged": False, "conflict": True, "files": conflicted}
        return {
            "merged": False,
            "reason": (proc.stderr.strip() or proc.stdout.strip() or "git merge failed"),
        }

    head = _git(project_dir, "rev-parse", "HEAD").stdout.strip()
    payload: dict[str, Any] = {"merged": True, "commit": head}
    if remove:
        payload["cleanup"] = remove_worktree(project_dir, story_id, force=False)
    return payload


# ─── remove ───────────────────────────────────────────────────────────────────


def remove_worktree(project_dir: str, story_id: str, force: bool = False) -> dict[str, Any]:
    """Remove the story worktree and delete its branch.

    force=True passes --force to `git worktree remove` (dirty worktrees)
    and uses `git branch -D` (unmerged branches).
    """
    err = _validate_story_id(story_id)
    if err:
        return _error(err)
    wt_path = _worktree_path(project_dir, story_id)
    if wt_path is None:
        return _error(f"story id {story_id!r} resolves outside the managed worktrees dir")
    branch = _branch_name(story_id)

    payload: dict[str, Any] = {
        "path": wt_path,
        "branch": branch,
        "removed": False,
        "branch_deleted": False,
    }

    if _find_registered(project_dir, wt_path) is not None:
        args = ["worktree", "remove"]
        if force:
            args.append("--force")
        args.append(wt_path)
        proc = _git(project_dir, *args)
        if proc.returncode != 0:
            return _error(f"git worktree remove failed: {proc.stderr.strip()}", **payload)
        payload["removed"] = True

    if _branch_exists(project_dir, branch):
        proc = _git(project_dir, "branch", "-D" if force else "-d", branch)
        if proc.returncode != 0:
            return _error(f"git branch delete failed: {proc.stderr.strip()}", **payload)
        payload["branch_deleted"] = True

    return payload


# ─── list ─────────────────────────────────────────────────────────────────────


def list_worktrees(project_dir: str, stale_only: bool = False) -> dict[str, Any]:
    """Report synaptory-managed worktrees.

    Each entry: {path, branch, merged, dir_exists}. `merged` means the
    branch is contained in the main tree's HEAD. stale_only filters to
    merged-or-missing-dir entries (candidates for cleanup).
    """
    registered = _registered_worktrees(project_dir)
    if registered is None:
        return _error("git worktree list failed")

    merged_proc = _git(project_dir, "branch", "--merged", "HEAD", "--format=%(refname:short)")
    merged_branches = (
        set(merged_proc.stdout.split()) if merged_proc.returncode == 0 else set()
    )

    managed_root = os.path.realpath(os.path.join(project_dir, WORKTREES_RELDIR))
    entries = []
    for wt in registered:
        path = os.path.realpath(wt["path"])
        try:
            if os.path.commonpath([managed_root, path]) != managed_root or path == managed_root:
                continue
        except ValueError:  # different drives on Windows
            continue
        entry = {
            "path": path,
            "branch": wt["branch"],
            "merged": wt["branch"] in merged_branches if wt["branch"] else False,
            "dir_exists": os.path.isdir(path),
        }
        if stale_only and not (entry["merged"] or not entry["dir_exists"]):
            continue
        entries.append(entry)
    return {"worktrees": entries}


# ─── CLI ──────────────────────────────────────────────────────────────────────


def _exit_code(payload: dict[str, Any]) -> int:
    if payload.get("error"):
        return EXIT_ERROR
    if payload.get("merged") is False:
        if payload.get("conflict"):
            return EXIT_CONFLICT
        if payload.get("reason") == "worktree_dirty":
            return EXIT_DIRTY
        return EXIT_ERROR
    return EXIT_OK


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="worktree_manager.py",
        description="Per-story git worktree lifecycle (create/merge/remove/list).",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_create = sub.add_parser("create", help="create (or reuse) a story worktree")
    p_create.add_argument("--project-dir", required=True)
    p_create.add_argument("--story-id", required=True)
    p_create.add_argument("--base", default="HEAD")

    p_commit = sub.add_parser(
        "commit", help="audited commit of the SE's worktree changes (run before merge)"
    )
    p_commit.add_argument("--project-dir", required=True)
    p_commit.add_argument("--story-id", required=True)
    p_commit.add_argument("--message", default=None)
    p_commit.add_argument(
        "--author", default=None, help="git author override, e.g. 'name <email>'"
    )

    p_merge = sub.add_parser("merge", help="merge the story branch into the main tree")
    p_merge.add_argument("--project-dir", required=True)
    p_merge.add_argument("--story-id", required=True)
    p_merge.add_argument(
        "--no-remove", action="store_true", help="keep the worktree + branch after merging"
    )

    p_remove = sub.add_parser("remove", help="remove a story worktree + branch")
    p_remove.add_argument("--project-dir", required=True)
    p_remove.add_argument("--story-id", required=True)
    p_remove.add_argument("--force", action="store_true")

    p_list = sub.add_parser("list", help="list synaptory-managed worktrees")
    p_list.add_argument("--project-dir", required=True)
    p_list.add_argument("--stale", action="store_true")

    args = parser.parse_args(argv)

    if args.command == "create":
        payload = create_worktree(args.project_dir, args.story_id, base=args.base)
    elif args.command == "commit":
        payload = commit_worktree(
            args.project_dir, args.story_id,
            message=args.message, author=args.author,
        )
    elif args.command == "merge":
        payload = merge_worktree(args.project_dir, args.story_id, remove=not args.no_remove)
    elif args.command == "remove":
        payload = remove_worktree(args.project_dir, args.story_id, force=args.force)
    else:  # list
        payload = list_worktrees(args.project_dir, stale_only=args.stale)

    print(json.dumps(payload, indent=2))
    return _exit_code(payload)


if __name__ == "__main__":
    sys.exit(main())
